	static constexpr bool ValidatePropertyRanges() {
		std::uint32_t next = 0;
		for (const auto& range : kUnicodePropertyRanges) {
			if (range.First != next || range.Last < range.First || range.Last >= kUnicodeCodepointLimit) {
				return false;
			}

			next = range.Last + 1;
		}

		return next == kUnicodeCodepointLimit;
	}

	static_assert(ValidatePropertyRanges());

	UnicodeCharacterProperties QueryUnicodeProperties(std::uint32_t codepoint) {
		if (codepoint >= kUnicodeCodepointLimit) {
			return {};
		}

		const auto found = std::lower_bound(kUnicodePropertyRanges.begin(), kUnicodePropertyRanges.end(), codepoint, [](const auto& range, std::uint32_t value) {
			return range.Last < value;
		});
		UnicodeCharacterProperties result;
		result.Category = found->Category;
		result.CombiningClass = found->CombiningClass;

		return result;
	}

